from shared.http_client import http_client, DEFAULT_TIMEOUT

def dispatch(webhook_id, payload):
    hook = db.query(Webhook).get(webhook_id)
    return http_client.post(hook.url, json=payload, timeout=DEFAULT_TIMEOUT)

# queue consumer: retries the handler on any exception, no dedup/idempotency key
def handle_cancel_message(msg):
    try:
        cancel_subscription(msg.sub_id)
    except Exception:
        requeue(msg)  # will call cancel_subscription again, including stripe_client.refund

class OrderService:
    def place_order(self, cart):
        order = self._create_order(cart)
        self._reserve_inventory(order)
        self._charge_payment(order)
        self._fulfill(order)  # packs, labels, and schedules carrier pickup -- same process, same deploy
        return order

    def _fulfill(self, order):
        pick_list = self._generate_pick_list(order)
        self._request_carrier_pickup(order, pick_list)
